import { test, expect } from '@playwright/test';

test.describe('Search Term Highlighting in Result Snippets', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should highlight search terms in result snippets when search is performed', async ({ page }) => {
    // Perform search with multiple terms
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('Playwright TypeScript test script');

    // Click search button
    const searchButton = page.getByRole('button', { name: 'Search' });
    await searchButton.click();

    // Wait for results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify results are displayed
    const resultContainer = page.getByTestId('search-results');
    await expect(resultContainer).toBeVisible();

    // Verify result snippets contain highlighted terms
    const resultItems = page.getByTestId('search-result-item');
    const firstResult = resultItems.first();
    const snippet = firstResult.getByTestId('result-snippet');
    await expect(snippet).toBeVisible();

    // Verify 'Playwright' is highlighted
    const playwrightTerm = page.getByText('Playwright');
    await expect(playwrightTerm).toHaveClass(/highlighted-term/);

    // Verify 'TypeScript' is highlighted
    const typescriptTerm = page.getByText('TypeScript');
    await expect(typescriptTerm).toHaveClass(/highlighted-term/);

    // Verify 'test script' is highlighted
    const testScriptTerm = page.getByText('test script');
    await expect(testScriptTerm).toHaveClass(/highlighted-term/);

    // Verify result title contains search terms
    const resultTitle = firstResult.getByTestId('result-title');
    await expect(resultTitle).toContainText('Playwright TypeScript test script');
  });

  test('should not highlight terms when search returns no results', async ({ page }) => {
    // Perform search with non-existent terms
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('xyz123 nonexistentterm');

    // Click search button
    const searchButton = page.getByRole('button', { name: 'Search' });
    await searchButton.click();

    // Wait for results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify no results message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify result container is empty
    const resultContainer = page.getByTestId('search-results');
    await expect(resultContainer).toBeVisible();
    const resultItems = page.getByTestId('search-result-item');
    await expect(resultItems).toHaveCount(0);

    // Verify no highlighted terms exist
    const highlightedTerms = page.locator('[data-testid="highlighted-term"]');
    await expect(highlightedTerms).toHaveCount(0);
  });
});
